* >Natural Source Code: DAILYSALES
* PROGRAM: DAILYSALES - DAILY SALES DETAIL REPORT
* DESCRIPTION: DETAILED SALES REPORT WITH LINE-ITEM DETAIL
*              BY STORE, PRODUCT, CATEGORY
* LIBRARY: RETAILCORE
* ADABAS FILES: 111 (ORDER), 112 (ORDER-LINE)
* CREATED: 2000-02-15  A. GARCIA
* MODIFIED: 2009-05-22 - ADDED PRODUCT DETAIL
* MODIFIED: 2017-08-10 - ADDED MARGIN ANALYSIS
* -------------------------------------------------------
DEFINE DATA
LOCAL
  1 #REPORT-DATE          (D)
  1 #TOTAL-LINES          (N8)
  1 #TOTAL-QTY            (N8)
  1 #TOTAL-REVENUE        (N13.2)
  1 #TOTAL-COST           (N13.2)
  1 #TOTAL-MARGIN         (N13.2)
  1 #MARGIN-PCT           (N5.2)
*
  1 DSO-VIEW VIEW OF ORDER-FILE
    2 DSO-ID               (N10)
    2 DSO-NUMBER           (A12)
    2 DSO-STATUS           (A3)
    2 DSO-STORE-ID         (N4)
    2 DSO-DATE             (D)
    2 DSO-TOTAL-AMT        (N11.2)
*
  1 DSL-VIEW VIEW OF ORDER-LINE-FILE
    2 DSL-ORDER-ID         (N10)
    2 DSL-LINE-NO          (N3)
    2 DSL-PROD-ID          (N8)
    2 DSL-SKU              (A15)
    2 DSL-DESCRIPTION      (A60)
    2 DSL-QTY-ORDERED      (N6)
    2 DSL-UNIT-PRICE       (N9.2)
    2 DSL-DISCOUNT-AMT     (N9.2)
    2 DSL-LINE-TOTAL       (N11.2)
    2 DSL-STATUS           (A3)
END-DEFINE
*
MOVE *DATX TO #REPORT-DATE
SUBTRACT 1 FROM #REPORT-DATE (D)
*
* -------------------------------------------------------
* LOAD REPORT CONFIGURATION
* -------------------------------------------------------
1 #CFG-VALUE    (A80)
1 #CFG-NUM      (N11.2)
1 #CFG-DATE     (D)
1 #CFG-FLAG     (A1)
1 #CFG-FOUND    (A1)
1 #MIN-LINE-AMT (N9.2) INIT <0>
*
CALLNAT 'CONFIGN' 'REPORT.SALES.MIN.LINE.AMT'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
IF #CFG-FOUND = 'Y'
  MOVE #CFG-NUM TO #MIN-LINE-AMT
END-IF
*
CALLNAT 'CONFIGN' 'REPORT.SALES.INCLUDE.MARGIN'
  #CFG-VALUE #CFG-NUM #CFG-DATE #CFG-FLAG #CFG-FOUND
1 #INCLUDE-MARGIN (A1) INIT <'N'>
IF #CFG-FOUND = 'Y'
  MOVE #CFG-FLAG TO #INCLUDE-MARGIN
END-IF
*
* VALIDATE AND FORMAT DATES
1 #DT-VALID   (A1)
1 #DT-ERR     (A60)
1 #DT-RESULT  (D)
1 #DT-STR     (A10)
1 #DT-NUM     (N5)
CALLNAT 'DATEU' 'VAL' #REPORT-DATE #REPORT-DATE 0 #DT-RESULT
  #DT-STR #DT-NUM #DT-VALID #DT-ERR
IF #DT-VALID NE 'Y'
  CALLNAT 'LOGERR' 600 'DAILYSALES: INVALID REPORT DATE'
    'E' 'DAILYSALES' *USER
  ESCAPE ROUTINE
END-IF
*
CALLNAT 'DATEU' 'FMT' #REPORT-DATE #REPORT-DATE 0 #DT-RESULT
  #DT-STR #DT-NUM #DT-VALID #DT-ERR
*
* CHECK IF BUSINESS DAY
1 #BUS-VALID (A1)
CALLNAT 'DATEU' 'BUS' #REPORT-DATE #REPORT-DATE 0 #DT-RESULT
  #DT-STR #DT-NUM #BUS-VALID #DT-ERR
*
WRITE 'RETAILCORE - DAILY SALES DETAIL REPORT'
WRITE '======================================='
WRITE 'REPORT DATE:' #DT-STR
IF #BUS-VALID NE 'Y'
  WRITE '** NOTE: NON-BUSINESS DAY **'
END-IF
WRITE ' '
WRITE 'ORDER      STORE LINE SKU            '
  'DESCRIPTION                        QTY   PRICE     TOTAL'
WRITE '---------- ----- ---- ---------------'
  ' ---------------------------------- ----- --------- -----------'
*
FIND DSO-VIEW WITH DSO-DATE = #REPORT-DATE
  IF DSO-STATUS = 'CAN'
    ESCAPE TOP
  END-IF
*
  FIND DSL-VIEW WITH DSL-ORDER-ID = DSO-ID
    IF DSL-STATUS = 'CAN'
      ESCAPE TOP
    END-IF
    ADD 1 TO #TOTAL-LINES
    ADD DSL-QTY-ORDERED TO #TOTAL-QTY
    ADD DSL-LINE-TOTAL TO #TOTAL-REVENUE
*
    WRITE DSO-NUMBER DSO-STORE-ID DSL-LINE-NO DSL-SKU
      DSL-DESCRIPTION (EM=XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX)
      DSL-QTY-ORDERED DSL-UNIT-PRICE DSL-LINE-TOTAL
  END-FIND
END-FIND
*
WRITE ' '
WRITE '---------- ----- ---- ---------------'
  ' ---------------------------------- ----- --------- -----------'
WRITE 'TOTAL LINES   :' #TOTAL-LINES
WRITE 'TOTAL QTY     :' #TOTAL-QTY
WRITE 'TOTAL REVENUE :' #TOTAL-REVENUE
*
* -------------------------------------------------------
* FORMAT TOTALS USING FORMATTING UTILITY
* -------------------------------------------------------
1 #FMT-OUT   (A132)
1 #FMT-IN    (A80)
CALLNAT 'FMTU' 'CURR' #FMT-IN #TOTAL-REVENUE ' ' 0 #FMT-OUT
WRITE 'FORMATTED REVENUE :' #FMT-OUT
*
IF #TOTAL-COST > 0
  CALLNAT 'FMTU' 'CURR' #FMT-IN #TOTAL-COST ' ' 0 #FMT-OUT
  WRITE 'FORMATTED COST    :' #FMT-OUT
  CALLNAT 'FMTU' 'CURR' #FMT-IN #TOTAL-MARGIN ' ' 0 #FMT-OUT
  WRITE 'FORMATTED MARGIN  :' #FMT-OUT
END-IF
*
* -------------------------------------------------------
* ENRICH TOP PRODUCTS WITH FULL PRODUCT DATA
* -------------------------------------------------------
WRITE ' '
WRITE 'TOP SELLING SKU VERIFICATION'
WRITE '============================='
1 #TOP-COUNT      (N4) INIT <0>
1 #PG-PROD-ID     (N8)
1 #PG-SKU         (A15)
1 #PG-PROD-DATA
  2 #PG-PD-ID        (N8)
  2 #PG-PD-SKU       (A15)
  2 #PG-PD-ITEM-NO   (A12)
  2 #PG-PD-NAME      (A60)
  2 #PG-PD-SHORT-DESC (A30)
  2 #PG-PD-LONG-DESC (A200)
  2 #PG-PD-STATUS    (A1)
  2 #PG-PD-TYPE      (A2)
  2 #PG-PD-BRAND     (A30)
  2 #PG-PD-MFGR      (A40)
  2 #PG-PD-UPC       (A13)
1 #PG-CAT
  2 #PG-PC-DEPT      (A4)
  2 #PG-PC-CLASS     (A4)
  2 #PG-PC-SUBCLASS  (A4)
  2 #PG-PC-PATH      (A60)
1 #PG-ATTR
  2 #PG-PA-COLOR     (A20)
  2 #PG-PA-SIZE      (A10)
  2 #PG-PA-WEIGHT    (N7.3)
  2 #PG-PA-PERISH    (A1)
  2 #PG-PA-HAZARD    (A1)
  2 #PG-PA-SEASON    (A1)
1 #PG-PRICE
  2 #PG-PP-COST      (N9.2)
  2 #PG-PP-PRICE     (N9.2)
  2 #PG-PP-MSRP      (N9.2)
  2 #PG-PP-MIN       (N9.2)
  2 #PG-PP-TAX       (A4)
  2 #PG-PP-CURR      (A3)
1 #PG-LIFECYCLE
  2 #PG-PL-INTRO     (D)
  2 #PG-PL-DISCO     (D)
  2 #PG-PL-CLEAR     (D)
  2 #PG-PL-LAST-SOLD (D)
1 #PG-FOUND    (A1)
1 #PG-ERR      (A60)
*
FIND DSL-VIEW WITH DSL-ORDER-ID GE 0
  IF DSL-STATUS NE 'CAN' AND DSL-PROD-ID > 0
    MOVE DSL-PROD-ID TO #PG-PROD-ID
    RESET #PG-SKU
    CALLNAT 'PRODGET' #PG-PROD-ID #PG-SKU #PG-PROD-DATA #PG-CAT
      #PG-ATTR #PG-PRICE #PG-LIFECYCLE #PG-FOUND #PG-ERR
    IF #PG-FOUND = 'Y'
      * VALIDATE SKU CONSISTENCY
      CALLNAT 'SKUVAL' DSL-SKU ' ' #PG-PROD-ID #PG-PD-NAME
        #PG-PD-STATUS #PG-PP-PRICE #PG-PP-TAX #PG-FOUND #PG-ERR
      IF #PG-FOUND NE 'Y'
        CALLNAT 'LOGERR' 601 #PG-ERR 'W' 'DAILYSALES' *USER
      END-IF
    END-IF
    ADD 1 TO #TOP-COUNT
  END-IF
  IF #TOP-COUNT >= 20
    ESCAPE BOTTOM
  END-IF
END-FIND
*
* -------------------------------------------------------
* LOOK UP CUSTOMER INFO FOR HIGH-VALUE ORDERS
* -------------------------------------------------------
WRITE ' '
WRITE 'HIGH-VALUE ORDER CUSTOMERS'
WRITE '=========================='
1 #HV-CUST-DATA
  2 #HV-ID       (N8)
  2 #HV-NO       (A10)
  2 #HV-TYPE     (A2)
  2 #HV-STATUS   (A1)
  2 #HV-TITLE    (A5)
  2 #HV-FNAME    (A30)
  2 #HV-LNAME    (A40)
  2 #HV-DOB      (D)
  2 #HV-GENDER   (A1)
1 #HV-CONTACT
  2 #HV-EMAIL    (A80)
  2 #HV-PH1      (A20)
  2 #HV-PH2      (A20)
  2 #HV-PH3      (A20)
1 #HV-ADDRESS
  2 #HV-ADDR1    (A40)
  2 #HV-ADDR2    (A40)
  2 #HV-CITY     (A30)
  2 #HV-STATE    (A2)
  2 #HV-ZIP      (A10)
  2 #HV-COUNTRY  (A3)
1 #HV-MEMBER
  2 #HV-MEM-FLAG (A1)
  2 #HV-MEM-ID   (A12)
  2 #HV-MEM-SINCE (D)
  2 #HV-LOY-TIER (A1)
  2 #HV-LOY-PTS  (N10)
  2 #HV-LIFE-SPEND (N11.2)
  2 #HV-YTD-SPEND  (N9.2)
1 #HV-FOUND     (A1)
1 #HV-ERR       (A60)
*
1 #HV-ORD-VIEW VIEW OF ORDER-FILE
  2 HVO-ID       (N10)
  2 HVO-CUST-ID  (N8)
  2 HVO-DATE     (D)
  2 HVO-TOTAL    (N11.2)
  2 HVO-STATUS   (A3)
*
FIND #HV-ORD-VIEW WITH HVO-DATE = #REPORT-DATE
  IF HVO-STATUS = 'CAN'
    ESCAPE TOP
  END-IF
  IF HVO-TOTAL >= 500 AND HVO-CUST-ID > 0
    CALLNAT 'CUSTGET' HVO-CUST-ID #HV-CUST-DATA #HV-CONTACT
      #HV-ADDRESS #HV-MEMBER #HV-FOUND #HV-ERR
    IF #HV-FOUND = 'Y'
      WRITE '  ORDER' HVO-ID 'AMT:' HVO-TOTAL
        'CUSTOMER:' #HV-FNAME #HV-LNAME
        'TIER:' #HV-LOY-TIER
    END-IF
  END-IF
  IF *COUNTER > 500
    ESCAPE BOTTOM
  END-IF
END-FIND
*
WRITE ' '
WRITE 'END OF REPORT'
*
* AUDIT LOG
CALLNAT 'AUDITN' 'RPT' 'DAILYSALES' 'R' 'REPORTS'
  ' ' ' ' 'DAILY SALES REPORT GENERATED'
*
END
